React NativeiOSAndroid <pre><code>import * as Sentry from '@sentry/react-native';
import { Logger, AnalyticsTracker } from '@squad-sports/core';

// Forward SDK errors to Sentry
Logger.shared.configure({
  sink: (level, message, context) =&gt; {
    if (level === 'error') {
      Sentry.captureMessage(message, { level: 'error', extra: context });
    } else {
      Sentry.addBreadcrumb({ message, level, data: context });
    }
  },
});

// Forward analytics to Sentry performance
AnalyticsTracker.shared.configure({
  customAdapter: (event) =&gt; {
    Sentry.addBreadcrumb({
      category: 'squad',
      message: event.name,
      data: event.properties,
    });
  },
});
</code></pre> <p>Also wire the <code>onError</code> prop:</p> <pre><code>&lt;SquadExperience
  partnerId="your-id"
  apiKey="your-key"
  onError={(error) =&gt; Sentry.captureException(error)}
/&gt;
</code></pre> <pre><code>import Sentry

SquadLogger.shared.sink = SentryLogSink()

class SentryLogSink: SquadLogSink {
    func log(level: SquadLogLevel, message: String, context: [String: Any]) {
        let breadcrumb = Breadcrumb(level: level == .error ? .error : .info, category: "squad")
        breadcrumb.message = message
        breadcrumb.data = context
        SentrySDK.addBreadcrumb(breadcrumb)

        if level == .error {
            SentrySDK.capture(message: message)
        }
    }
}
</code></pre> <pre><code>import io.sentry.Sentry
import io.sentry.Breadcrumb
import io.sentry.SentryLevel

SquadLogger.handler = { level, tag, message -&gt;
    val breadcrumb = Breadcrumb().apply {
        this.category = "squad"
        this.message = "[$tag] $message"
        this.level = when (level) {
            SquadLogLevel.ERROR -&gt; SentryLevel.ERROR
            SquadLogLevel.WARN -&gt; SentryLevel.WARNING
            else -&gt; SentryLevel.INFO
        }
    }
    Sentry.addBreadcrumb(breadcrumb)

    if (level == SquadLogLevel.ERROR) {
        Sentry.captureMessage("[$tag] $message", SentryLevel.ERROR)
    }
}
</code></pre>

React NativeiOSAndroid <pre><code>import crashlytics from '@react-native-firebase/crashlytics';
import { Logger } from '@squad-sports/core';

Logger.shared.configure({
  sink: (level, message, context) =&gt; {
    crashlytics().log(`[Squad:${level}] ${message}`);
    if (level === 'error') {
      crashlytics().recordError(new Error(message));
    }
  },
});
</code></pre> <pre><code>import FirebaseCrashlytics

SquadLogger.shared.sink = CrashlyticsLogSink()

class CrashlyticsLogSink: SquadLogSink {
    func log(level: SquadLogLevel, message: String, context: [String: Any]) {
        Crashlytics.crashlytics().log("[Squad:\(level)] \(message)")
        if level == .error {
            Crashlytics.crashlytics().record(error: NSError(
                domain: "SquadSDK", code: -1,
                userInfo: [NSLocalizedDescriptionKey: message]
            ))
        }
    }
}
</code></pre> <pre><code>import com.google.firebase.crashlytics.FirebaseCrashlytics

SquadLogger.handler = { level, tag, message -&gt;
    FirebaseCrashlytics.getInstance().log("[$tag:$level] $message")
    if (level == SquadLogLevel.ERROR) {
        FirebaseCrashlytics.getInstance().recordException(RuntimeException("[$tag] $message"))
    }
}
</code></pre>

React Native (Expo)iOSAndroid <pre><code>import * as Notifications from 'expo-notifications';
import { PushNotificationHandler } from '@squad-sports/react-native';

Notifications.addNotificationResponseReceivedListener(response =&gt; {
  const data = response.notification.request.content.data;
  const action = PushNotificationHandler.handleNotification(data);
  if (action) {
    // Navigate to the Squad screen
    navigation.navigate(action.screen, action.params);
  }
});
</code></pre> <pre><code>import UserNotifications
import SquadSportsSDK

class AppDelegate: UIResponder, UIApplicationDelegate, UNUserNotificationCenterDelegate {

    func userNotificationCenter(
        _ center: UNUserNotificationCenter,
        didReceive response: UNNotificationResponse
    ) async {
        let userInfo = response.notification.request.content.userInfo
        if let action = SquadPushHandler.handleNotification(userInfo: userInfo) {
            SquadSDK.shared?.router?.push(action.route)
        }
    }
}
</code></pre> <pre><code>import com.google.firebase.messaging.FirebaseMessagingService
import com.google.firebase.messaging.RemoteMessage
